def bg(g):
    return Counter(v for r in g for v in r).most_common(1)[0][0]
# Pattern: fill extension cells with predicted pattern; if prediction ambiguous (no nonzero pred), paint with 1?
# Pair 6 row 14/15: pattern continues but changed cells are 1 even where pred==row[pos-p]... e.g. out has 7 at some positions where pattern would give 7 (not changed!). So changed = pattern cells only, i.e. painted where pattern says non-bg AND input was bg.
def f(g, verbose=False):
    o=[r[:] for r in g]; h,w=len(g),len(g[0]); BSG=bg(g)
    for r in range(h):
        row=o[r]
        nz=[c for c,v in enumerate(row) if v!=BSG]
        if not nz: continue
        last=max(nz)
        p=None
        for pp in range(1, w-last):
            ok=True
            for pos in range(last-2*pp+1,last+1):
                if pos>=pp and row[pos]!=row[pos-pp]:
                    ok=False;break
            if ok: p=pp;break
        if p is None: p=w-last # fallback
        for c in range(last+1,w):
            idx=c-(last+1)+p
            if idx<=last:
                pred=row[idx]
                if pred!=BSG and row[c]==BSG:
                    o[r][c]=pred   # or 1? check
    return o
